using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var camGo = GameObject.Find("IsoCamera");
        if (camGo == null) camGo = GameObject.Find("Main Camera");
        if (camGo == null) { result.Log("no camera"); return; }
        var cam = camGo.GetComponent<Camera>();
        if (cam == null) { result.Log("no Camera"); return; }
        result.Log("camera: " + cam.name + " pos=" + cam.transform.position);
        var rt = RenderTexture.GetTemporary(1920, 1080, 24, RenderTextureFormat.ARGB32);
        var prevTarget = cam.targetTexture;
        var prevActive = RenderTexture.active;
        cam.targetTexture = rt;
        cam.Render();
        RenderTexture.active = rt;
        var tex = new Texture2D(1920, 1080, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 1920, 1080), 0, 0);
        tex.Apply();
        var bytes = tex.EncodeToPNG();
        var dir = "C:/Users/casey/Desktop/Homesteader/tools/.scratch";
        if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
        File.WriteAllBytes(dir + "/hud_screenshot.png", bytes);
        result.Log("wrote bytes=" + bytes.Length);
        cam.targetTexture = prevTarget;
        RenderTexture.active = prevActive;
        RenderTexture.ReleaseTemporary(rt);
        Object.DestroyImmediate(tex);
    }
}
